"import json
import pandas as pd
from pathlib import Path

repo_dir = Path("C:/Users/Chethan S/.gemini/antigravity-ide/scratch/hackerrank-orchestrate-october26")
truth = pd.read_csv(repo_dir / "dataset/sample_output.csv")
audit_records = {}
for _, r in truth.iterrows():
    steps = json.loads(r['steps_json'])
    for s in steps:
        if s['system_id'] == 'security_service':
            audit_records[s['resource_id']] = r['case_id']

print(f"Searching for {len(audit_records)} audit records across dataset files...")

dataset_dir = repo_dir / "dataset"
