        try:
            content = p.read_text(encoding='utf-8', errors='ignore')
            for rec in audit_records:
                if rec in content:
                    if rec not in found_locations:
                        found_locations[rec] = []
                    found_locations[rec].append(str(p.relative_to(dataset_dir)))
        except Exception as e:
            pass

for rec, locs in found_locations.items():
    print(f"{rec} (from {audit_records[rec]}): {locs}")
